WITH latest AS (SELECT *, RANK() OVER (PARTITION BY promo_code ORDER BY ends_on) AS rn FROM promotions QUALIFY rn = 1), metrics AS (SELECT id, promo_code, ends_on, discount_pct, LAST_VALUE(channel, TRUE) OVER (ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel, PERCENT_RANK() OVER w_grp AS discount_pct_percent_rank FROM latest WHERE rn > 1 WINDOW w_grp AS (PARTITION BY channel, promo_code ORDER BY discount_pct DESC)), latest_promotions AS (SELECT * FROM metrics QUALIFY RANK() OVER (PARTITION BY promo_code ORDER BY discount_pct DESC) = 1), with_windows AS (SELECT *, LAG(discount_pct, 1) OVER w_ordered AS prev_discount_pct, NTILE(10) OVER w_ordered AS discount_pct_bucket, LAG(discount_pct, 2) OVER (PARTITION BY promo_code ORDER BY discount_pct_percent_rank, id) AS prev_discount_pct_2 FROM latest_promotions WINDOW w_ordered AS (PARTITION BY promo_code ORDER BY discount_pct, id)), filtered AS (SELECT *, TRIM(promo_code) AS clean_promo_code FROM with_windows WHERE ends_on >= TO_DATE('2023-08-19')) SELECT DATE_TRUNC('QUARTER', ends_on) AS quarter_start, COUNT(DISTINCT promo_code) AS distinct_promo_codes, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, COUNT(CASE WHEN promo_code = 'SPRING10' THEN 1 END) AS spring10_count, ROUND(AVG(discount_pct_percent_rank), 2) AS avg_discount_pct_percent_rank FROM filtered GROUP BY DATE_TRUNC('QUARTER', ends_on) HAVING avg_discount_pct_percent_rank > 0;
